items.text:
Окей, давай сделаем рабочий пример для Godot 4, где сигнал передаёт JSON-пакет от WebSocket к другому узлу.  

---

### 1️⃣ Сценарий

- Узел `WebSocketNode` получает данные от сервера.  
- Он излучает сигнал `message_received(packet)` с JSON-объектом.  
- Узел `UI` подписан на этот сигнал и обрабатывает пакет.  

---

### 2️⃣ Скрипт `WebSocketNode.gd`

```gdscript
extends Node

signal message_received(packet: Dictionary[String, Variant])

@export var websocket_url = "ws://localhost:3000/ws"
var socket := WebSocketClient.new()

func _ready():
	socket.connect_to_url(websocket_url)
	set_process(true)

func _process(_delta):
	if socket.get_connection_status() == WebSocketClient.CONNECTION_CONNECTED:
		while socket.get_available_packet_count() > 0:
			var packet_bytes = socket.get_packet()
			var packet_string = packet_bytes.get_string_from_utf8()

			# Парсим JSON
			var parsed = JSON.parse_string(packet_string)
			if typeof(parsed) == TYPE_DICTIONARY:
				var packetObj: Dictionary[String, Variant] = parsed as Dictionary[String, Variant]
				emit_signal("message_received", packetObj)
			else:
				push_warning("Принято не словарь JSON: %s" % packet_string)
```

---

### 3️⃣ Скрипт `UI.gd`

```gdscript
extends Control

@onready var ws_node = $WebSocketNode

func _ready():
	ws_node.connect("message_received", self, "_on_message_received")

func _on_message_received(packet: Dictionary[String, Variant]):
	print("Получен пакет:", packet)
	# Например, вывести конкретные поля
	if packet.has("response"):
		print("Response:", packet["response"])
	if packet.has("payload"):
		print("Payload:", packet["payload"])
```

---

### 4️⃣ Пояснения

1. **Сигнал**: `message_received(packet)` — передаёт весь JSON-пакет.  
2. **Парсинг JSON**: используем `JSON.parse_string()`, проверяем `typeof(parsed) == TYPE_DICTIONARY` и приводим к `Dictionary[String, Variant]`.  
3. **Подключение сигнала**: `connect("message_received", self, "_on_message_received")` — теперь `UI` автоматически получает каждый пакет.  

---

